thread_local! {
    static API: RefCell<Option<Box<dyn PlayerApi>>> = const { RefCell::new(None) };
}

/// Installs the implementation (call on the Python thread before the interpreter runs scripts).
pub fn set_api(api: Box<dyn PlayerApi>) {
    API.with(|a| *a.borrow_mut() = Some(api));
}

fn with_api<R>(f: impl FnOnce(&mut dyn PlayerApi) -> R) -> Option<R> {
    API.with(|a| a.borrow_mut().as_mut().map(|b| f(b.as_mut())))
}

/// C entry point for `player.ActEmotion(vid: int) -> none`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn m2_player_act_emotion(vid: i32) -> M2Result {
    match with_api(|api| api.act_emotion(vid)) {
        None => no_api("player"),
        Some(Err(e)) => fail(e),
        Some(Ok(_v)) => {
            
            ok()
        }
    }
}

